-- State transitions declared for PosInvoice: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION pos.pos_invoices_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'paid'), ('paid', 'returned'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: pos_invoices.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_pos_invoices__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS pos_invoices_status_transition_check ON pos.pos_invoices;
CREATE TRIGGER pos_invoices_status_transition_check
    BEFORE UPDATE OF "status" ON pos.pos_invoices
    FOR EACH ROW EXECUTE FUNCTION pos.pos_invoices_status_transition_check();
